 }\n})\nuseOnOffcanvasHide('form-offcanvas', () => setFormData(defaultData()))\n\n/*\n * Form Data & Validation & Handeling\n */\n// Default FORM DATA\nconst defaultData = () => {\n  ISREADONLY.value = false\n  errorMessages.value = {}\n  return {\n    height_cm: 0,\n    height_inch:0,\n    weight_kg:0,\n    weight_pound:0,\n    bmi:0,\n    bmr:0,\n    tbf:0,\n    sm:0,\n    tbw:0,\n    bmc:0,\n    vfi:null,\n    customer_id:null,\n    height_meter:0,\n\n  }\n}\n\nconst singleSelectOption = ref({\ncreateOption: true,\ncloseOnSelect: true,\nsearchable: true\n})\n\n\nconst customer = ref({ options: [], list: [] })\n\nconst customerSelect = (value) => {\nif (_.isString(value)) {\n  newCustomerData.value = {\n    first_name: value.split(' ')[0] || '',\n    last_name: value.split(' ')[1] || ''\n  }\n  bootstrap.Modal.getOrCreateInstance($('#exampleModal')).show()\n  customer_id.value = null\n}\n}\n\nconst getCustomers = (cb) =>\nuseSelect({ url: CUSTOMER_LIST }, { value: 'id', label: 'full_name' }).then((data) => {\n  customer.value = data\n  if (typeof cb == 'function') {\n    cb()\n  }\n})\n\n\nconst setFormData = (data) => {\n  resetForm({\n    values: {\n    height_cm: data.height_cm,\n    height_inch:data.height_inch,\n    weight_kg:data.weight_kg,\n    weight_pound:data.weight_pound,\n    bmi:data.bmi,\n    bmr:data.bmr,\n    tbf:data.tbf,\n    sm:data.sm,\n    tbw:data.tbw,\n    bmc:data.bmc,\n    vfi:data.vfi,\n    customer_id:data.customer_id,\n    }\n  })\n}\n\n // Reload Datatable, SnackBar Message, Alert, Offcanvas Close\n const reset_datatable_close_offcanvas = (res) => {\n  IS_SUBMITED.value = false\n  if (res.status) {\n    window.successSnackbar(res.message)\n    renderedDataTable.ajax.reload(null, false)\n    bootstrap.Offcanvas.getInstance('#vitalform-offcanvas').hide()\n    setFormData(defaultData())\n\n  } else {\n    window.errorSnackbar(res.message)\n    errorMessages.value = res.all_message\n  }\n}\n\n// Validations\nconst validationSchema = yup.ob